-- organizations: the current org, plus orgs the current user belongs to (names for the
-- switcher). Updates only in the current org. Creation goes through create_organization().
CREATE POLICY organizations_select ON organizations FOR SELECT
  USING (
    id = app_org_id()
    OR EXISTS (
      SELECT 1 FROM memberships m
      WHERE m.org_id = organizations.id AND m.user_id = app_user_id()
    )
  );
--> statement-breakpoint
CREATE POLICY organizations_update ON organizations FOR UPDATE
  USING (id = app_org_id()) WITH CHECK (id = app_org_id());
--> statement-breakpoint

-- users: yourself, and co-members of the current org (member lists).
CREATE POLICY users_select ON users FOR SELECT
