-- -----------------------------------------------------------------------------------------
-- SECURITY DEFINER functions: the only reviewed paths that act without a user or org
-- context. They run as ig_owner (which RLS does not bind), take hashed tokens rather than
-- secrets, and return the minimum. pg_temp is last on the search_path so it cannot shadow.
-- -----------------------------------------------------------------------------------------

-- Login, magic link, password reset and signup need a user by email before any context.
CREATE FUNCTION auth_find_user_by_email(p_email citext)
RETURNS TABLE (
  id uuid, email citext, name text, email_verified_at timestamptz, password_hash text
)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $$
  SELECT u.id, u.email, u.name, u.email_verified_at, c.password_hash
  FROM users u
  LEFT JOIN user_credentials c ON c.user_id = u.id
  WHERE u.email = p_email
$$;
--> statement-breakpoint

-- Signup. Always creates an unverified user; a duplicate email raises unique_violation.
CREATE FUNCTION auth_register_user(p_email citext, p_name text, p_password_hash text)
RETURNS uuid
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
  v_user uuid;
BEGIN
  INSERT INTO users (email, name) VALUES (p_email, p_name) RETURNING users.id INTO v_user;
  INSERT INTO user_credentials (user_id, password_hash) VALUES (v_user, p_password_hash);
  RETURN v_user;
END
$$;
--> statement-breakpoint

-- Every authenticated request: a live session by token hash, with its user and role in the
-- active org.
CREATE FUNCTION auth_session_lookup(p_token_hash bytea)
RETURNS TABLE (
  session_id uuid, user_id uuid, expires_at timestamptz, active_org_id uuid,
  role membership_role, email citext, name text, email_verified_at timestamptz
)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $$
  SELECT s.id, s.user_id, s.expires_at, s.active_org_id,
         m.role, u.email, u.name, u.email_verified_at
  FROM sessions s
  JOIN users u ON u.id = s.user_id
  LEFT JOIN memberships m ON m.org_id = s.active_org_id AND m.user_id = s.user_id
  WHERE s.token_hash = p_token_hash AND s.expires_at > now()
$$;
--> statement-breakpoint

-- Email links. Atomically marks a live token used and returns its user, or NULL. Using one
-- token retires the user's other open tokens of that purpose. Every purpose proves control
-- of the mailbox, so the email counts as verified.
CREATE FUNCTION auth_consume_token(p_token_hash bytea, p_purpose auth_token_purpose)
RETURNS uuid
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
  v_user uuid;
BEGIN
  UPDATE auth_tokens t SET used_at = now()
  WHERE t.token_hash = p_token_hash
    AND t.purpose = p_purpose
    AND t.used_at IS NULL
    AND t.expires_at > now()
  RETURNING t.user_id INTO v_user;

  IF v_user IS NULL THEN
    RETURN NULL;
  END IF;

  UPDATE auth_tokens t SET used_at = now()
  WHERE t.user_id = v_user AND t.purpose = p_purpose AND t.used_at IS NULL;

  UPDATE users u SET email_verified_at = now()
  WHERE u.id = v_user AND u.email_verified_at IS NULL;

  RETURN v_user;
END
$$;
--> statement-breakpoint

-- Invite links are opened before the invitee has any context in the org.
CREATE FUNCTION invite_lookup(p_token_hash bytea)
RETURNS TABLE (
  invite_id uuid, org_id uuid, org_name text, email citext, role membership_role,
  expires_at timestamptz, accepted_at timestamptz, revoked_at timestamptz
)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $$
  SELECT i.id, i.org_id, o.name, i.email, i.role, i.expires_at, i.accepted_at, i.revoked_at
  FROM invites i
  JOIN organizations o ON o.id = i.org_id
  WHERE i.token_hash = p_token_hash
$$;
--> statement-breakpoint

-- Creates an org and makes the current user (app.user_id) its owner, atomically, so no org
-- ever exists without an owner. The slug gets a random suffix; collisions are retried.
CREATE FUNCTION create_organization(p_name text, p_slug_base text)
RETURNS uuid
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
  v_user uuid := app_user_id();
  v_org uuid;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'create_organization requires a user context'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_slug_base IS NULL OR p_slug_base !~ '^[a-z0-9]+(-[a-z0-9]+)*$'
     OR char_length(p_slug_base) > 40 THEN
    RAISE EXCEPTION 'invalid slug base' USING ERRCODE = 'check_violation';
  END IF;

  FOR attempt IN 1..5 LOOP
    BEGIN
      INSERT INTO organizations (name, slug)
      VALUES (p_name, p_slug_base || '-' || encode(gen_random_bytes(3), 'hex'))
      RETURNING organizations.id INTO v_org;
      EXIT;
    EXCEPTION WHEN unique_violation THEN
      IF attempt = 5 THEN
        RAISE;
      END IF;
    END;
  END LOOP;

  INSERT INTO memberships (org_id, user_id, role) VALUES (v_org, v_user, 'owner');
  RETURN v_org;
END
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION
  auth_find_user_by_email(citext),
  auth_register_user(citext, text, text),
  auth_session_lookup(bytea),
  auth_consume_token(bytea, auth_token_purpose),
  invite_lookup(bytea),
  create_organization(text, text)
FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION
  auth_find_user_by_email(citext),
  auth_register_user(citext, text, text),
  auth_session_lookup(bytea),
  auth_consume_token(bytea, auth_token_purpose),
  invite_lookup(bytea),
  create_organization(text, text)
TO ig_app;
--> statement-breakpoint

-- -----------------------------------------------------------------------------------------
-- audit_log is append-only for every role, including the owner (FR-ADM-1, ADR-0016).
-- -----------------------------------------------------------------------------------------
CREATE FUNCTION audit_log_reject_change() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'audit_log is append-only: % is not allowed', TG_OP
    USING ERRCODE = 'IG001';
END
$$;
--> statement-breakpoint
CREATE TRIGGER audit_log_append_only BEFORE UPDATE OR DELETE ON audit_log
  FOR EACH ROW EXECUTE FUNCTION audit_log_reject_change();
--> statement-breakpoint
CREATE TRIGGER audit_log_no_truncate BEFORE TRUNCATE ON audit_log
  FOR EACH STATEMENT EXECUTE FUNCTION audit_log_reject_change();
